-- ====================================================================
-- SejarahWira  |  ERA 9: Sukan Kebanggaan Malaysia  |  seed_era9.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) badminton dan bola sepak, (2) olahraga dan hoki,
-- (3) atlet kebanggaan negara, (4) sukan sebagai alat perpaduan, (5) penganjuran sukan antarabangsa di Malaysia,
-- (6) tokoh inspirasi sukan negara. Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Siaran Langsung Stadium Kebanggaan Negara)  = Pengulas Sukan (NPC 161)
--   Naratif 2 (Latihan Pagi Jurulatih Sekolah)             = Jurulatih Sekolah (NPC 162)
--   Naratif 3 (Buku Skrap Peminat Sukan Negara)            = Murid Peminat Sukan (NPC 163)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (NPC 161-182 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era9.sql
-- Selamat dijalankan berulang kali (kandungan Era 9 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: kandungan sukan mengikut bahan asal sahaja; senarai atlet dan tokoh tidak diberi sukan atau pencapaian tambahan.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 9 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 9;

-- 2. NPC baharu Era 9 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 9 (50 soalan aneka pilihan, ID 901-950)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 9;


COMMIT;